/**
 * Regenerates src/lib/icons/bundle.ts from the icon names used in the source.
 *
 * `@iconify/react` fetches every icon it has never seen from api.iconify.design,
 * so each page opened with three blocking requests to a third party and every
 * icon rendered as a zero-width span until its data arrived — which is what the
 * listing pages' layout shift was. Bundling the icons the site actually names
 * removes both. Icon keys that come from the CMS still fall back to the API.
 *
 * Run: node scripts/build-icon-bundle.mjs
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync } from "node:fs";
import { join, dirname } from "node:path";

const SRC = "src";
const OUT = "src/lib/icons/bundle.ts";

function walk(dir) {
  return readdirSync(dir).flatMap((entry) => {
    const p = join(dir, entry);
    if (statSync(p).isDirectory()) return walk(p);
    return p.endsWith(".ts") || p.endsWith(".tsx") ? [p] : [];
  });
}

// Only collections we actually depend on; this keeps Tailwind variants such as
// `lg:grid-cols-3` and Node's `node:path` out of the icon list.
const COLLECTIONS = ["ph", "solar", "mdi", "lineicons"];
const NAME_RE = new RegExp(`["'](${COLLECTIONS.join("|")}):([a-z0-9-]+)["']`, "g");

const wanted = new Map();
for (const file of walk(SRC)) {
  const normalised = file.split("\\").join("/");
  if (normalised === OUT) continue;
  const text = readFileSync(file, "utf8");
  for (const [, prefix, name] of text.matchAll(NAME_RE)) {
    if (!wanted.has(prefix)) wanted.set(prefix, new Set());
    wanted.get(prefix).add(name);
  }
}

const collections = [];
for (const [prefix, names] of [...wanted].sort()) {
  const list = [...names].sort();
  const url = `https://api.iconify.design/${prefix}.json?icons=${list.join(",")}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${prefix}: ${res.status} ${res.statusText}`);
  const data = await res.json();
  const missing = list.filter((n) => !data.icons?.[n] && !data.aliases?.[n]);
  if (missing.length) console.warn(`  ! ${prefix}: not found — ${missing.join(", ")}`);
  console.log(`  ${prefix}: ${Object.keys(data.icons ?? {}).length} icons`);
  collections.push(data);
}

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(
  OUT,
  `"use client";

// GENERATED by scripts/build-icon-bundle.mjs — do not edit by hand.
//
// Icon data for every icon this codebase names, so @iconify/react resolves them
// synchronously instead of fetching api.iconify.design on first paint. Re-run
// the script after adding an icon; anything missing here still loads from the
// API, it just costs a round trip and a layout shift.
import { addCollection } from "@iconify/react";

const collections = ${JSON.stringify(collections)};

let registered = false;

/** Idempotent: the module is imported from more than one client entry point. */
export function registerBundledIcons(): void {
  if (registered) return;
  registered = true;
  for (const collection of collections) {
    addCollection(collection as never);
  }
}

registerBundledIcons();
`,
  "utf8"
);
console.log(`wrote ${OUT} (${(statSync(OUT).size / 1024).toFixed(1)} KB)`);
